import{_ as t,o as i,c as e,a5 as c}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Báo cáo luồng tạo content hiện tại","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/ai-content-flow-2026-11-03.md","filePath":"architecture/ai-content-flow-2026-11-03.md"}'),a={name:"architecture/ai-content-flow-2026-11-03.md"};function h(o,n,d,r,s,g){return i(),e("div",null,[...n[0]||(n[0]=[c(`<h1 id="bao-cao-luong-tao-content-hien-tai" tabindex="-1">Báo cáo luồng tạo content hiện tại <a class="header-anchor" href="#bao-cao-luong-tao-content-hien-tai" aria-label="Permalink to &quot;Báo cáo luồng tạo content hiện tại&quot;">​</a></h1><p>Ngày đối chiếu: 03/11/2026. Phạm vi: code local và các tên provider/model trong <code>.env</code> của AI Service. Đã đọc kiểm chứng Neo4j thật; chưa gọi AI sinh caption thật, kiểm kê toàn bộ database hoặc xác nhận tiến trình đang chạy đã nạp cấu hình mới.</p><h2 id="_1-ket-luan" tabindex="-1">1. Kết luận <a class="header-anchor" href="#_1-ket-luan" aria-label="Permalink to &quot;1. Kết luận&quot;">​</a></h2><p>Hiện có hai nhánh tạo văn bản riêng trong cùng giao diện. Nhánh Generate with AI chỉ dùng thông tin form và một phần nội dung đang soạn. Nhánh tạo ba caption tự gom thêm dữ liệu brand/client, bài đã đăng, tài liệu RAG và trend được chọn. Với trend sự kiện của pipeline, nhánh ba caption đã bổ sung các thực thể được nhắc đến và bài nguồn từ Neo4j. Humanizer đã được đưa vào prompt của cả hai nhánh.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    U[Người dùng mở AI Content] --&gt; Q[Generate with AI]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    U --&gt; C[Tạo 3 phương án caption]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Q --&gt; F[Prompt + giọng văn + nền tảng + yêu cầu hashtag]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; X[Gom context theo workspace]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    P[(PostgreSQL: workspace và client)] --&gt; X</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M[(MongoDB: bài đã đăng)] --&gt; X</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R[(ChromaDB: tài liệu brand)] --&gt; X</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T[Trend đã chọn: Redis và danh mục nội bộ] --&gt; X</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G[(Neo4j: bài nguồn và thực thể của trend đã chọn)] --&gt; X</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; L[Ghép prompt và quy tắc Humanizer]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    X --&gt; L</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L --&gt; A[Gọi model qua API]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A --&gt; V[Phân tích kết quả và kiểm duyệt]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    V --&gt; W[Trả bài và hashtag về giao diện]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    W --&gt; E[Người dùng chọn áp dụng vào trình soạn thảo]</span></span></code></pre></div><p>Sơ đồ thể hiện nguồn có trong code; không khẳng định tất cả các nguồn hiện có dữ liệu. Quyền truy cập và credit được xử lý tại Business Service trước khi gọi AI.</p><h2 id="_2-nhanh-generate-with-ai" tabindex="-1">2. Nhánh Generate with AI <a class="header-anchor" href="#_2-nhanh-generate-with-ai" aria-label="Permalink to &quot;2. Nhánh Generate with AI&quot;">​</a></h2><ol><li><code>editor/index.tsx</code> chuyển tối đa 180 ký tự đầu của caption đang soạn làm <code>topic</code> cho panel.</li><li><code>AIGeneratePanel</code> gửi prompt người dùng nhập, topic, giọng văn, nền tảng và số hashtag yêu cầu. Khi tạo lại, gửi thêm phản hồi và caption trước.</li><li><code>aiGenerationService.generatePost</code> nối các phần trên thành một trường <code>topic</code>, gọi <code>POST /api/v1/ai/content/generate</code> qua gateway và Business Service.</li><li>Business Service xác thực người dùng/workspace, giữ credit, chống xử lý trùng khi dùng cùng khóa idempotency, rồi chuyển payload sang AI Service. Nó bổ sung <code>client_id</code> và <code>workspace_id</code> nhưng nhánh này không dùng các ID đó để truy vấn brand hoặc RAG.</li><li>AI Service ghép system prompt, tone, hướng dẫn nền tảng và Humanizer rồi gọi LLM. Nó trích hashtag từ văn bản bằng biểu thức chính quy và chạy kiểm duyệt nội dung.</li><li>Web nhận caption, hashtag, trạng thái kiểm duyệt. Hashtag được cắt theo số lượng người dùng yêu cầu. Người dùng bấm áp dụng để cập nhật editor; việc tạo content không tự đăng bài.</li></ol><p><strong>Dữ liệu chưa được lấy trong nhánh này:</strong> hồ sơ workspace/client, bài cũ trong MongoDB, tài liệu ChromaDB, trend-fit, ảnh sản phẩm. Một lần gọi sinh văn bản bình thường cho ra một bài, không phải ba phương án. Không có bước PhoBERT hoặc kiểm tra số liệu của <code>caption_service</code> trên nhánh này.</p><h2 id="_3-nhanh-tao-ba-phuong-an-caption" tabindex="-1">3. Nhánh tạo ba phương án caption <a class="header-anchor" href="#_3-nhanh-tao-ba-phuong-an-caption" aria-label="Permalink to &quot;3. Nhánh tạo ba phương án caption&quot;">​</a></h2><p>Web gọi <code>POST /api/v1/workspaces/{workspaceId}/ai/captions</code>. Request chứa chủ đề, tone, nền tảng, độ dài, ngôn ngữ, mục tiêu bài; có thể có <code>taskId</code>, <code>trendId</code> và kỹ thuật bắt trend.</p><table tabindex="0"><thead><tr><th>Nguồn</th><th>Dữ liệu code đang lấy</th><th>Điều kiện / giới hạn</th></tr></thead><tbody><tr><td>Form người dùng</td><td>Chủ đề, mục tiêu, giọng văn, nền tảng, độ dài, VI/EN</td><td>Luôn dùng</td></tr><tr><td>PostgreSQL <code>workspaces</code></td><td>Tên, ngành, tagline, mô tả</td><td>Theo workspace hiện tại</td></tr><tr><td>PostgreSQL <code>workspace_members</code> + <code>client_profiles</code></td><td>Công ty, ngành, tagline, mô tả của tối đa ba thành viên CLIENT đang hoạt động</td><td>Chưa chọn riêng một client/sản phẩm cho lần viết</td></tr><tr><td>PostgreSQL <code>tasks</code></td><td>Tiêu đề task</td><td>Chỉ khi có <code>taskId</code>; chưa lấy toàn bộ brief hoặc content request liên kết</td></tr><tr><td>MongoDB <code>posts</code></td><td>Tối đa ba bài <code>PUBLISHED</code> gần nhất của workspace</td><td>Mỗi bài tối đa 600 ký tự; dùng làm mẫu giọng, không làm nguồn bịa dữ kiện</td></tr><tr><td>ChromaDB <code>brandhub_rag</code></td><td>Tối đa ba đoạn tài liệu liên quan đến chủ đề</td><td>Lọc metadata <code>clientId = workspaceId</code>; mỗi đoạn tối đa 800 ký tự; lỗi/không có thì tiếp tục với danh sách rỗng</td></tr><tr><td>Trend đã chọn</td><td>Trend card: sự kiện/moment, keywords, ví dụ, cách áp dụng</td><td>Chỉ khi người dùng chọn; tra cứu lại bằng ID tại AI Service</td></tr><tr><td>Neo4j</td><td>Bài nguồn và người/địa điểm/tổ chức/sản phẩm/sự kiện được nhắc trong các bài đó</td><td>Chỉ với trend pipeline đã được tra cứu hợp lệ; tối đa 3 nguồn, 12 lượt nhắc, 3.000 ký tự</td></tr><tr><td>Brand profile</td><td>Tên, ngành, mô tả; <code>voice_level=1</code>, <code>emoji=few</code></td><td>Business chỉ gửi profile này khi có <code>trendId</code>; giọng vẫn là mặc định</td></tr></tbody></table><p>RAG dùng embedding <code>intfloat/multilingual-e5-small</code> để tìm đoạn tài liệu gần với chủ đề. Nó truy vấn kho đã nhập trước đó, không tự tìm thông tin sản phẩm trên Internet.</p><p>Nguồn trend gồm:</p><ul><li>Lịch dịp/lễ tại <code>app/data/moments_vn.json</code>.</li><li>Format/meme đã nhập tại <code>app/data/trend_formats.json</code>.</li><li>Kết quả pipeline AI-05 đã công bố trong Redis snapshot/live cache. Bấm tạo caption không tự chạy lại crawler hoặc T1–T7.</li></ul><p>Trend-fit lọc theo luật, dùng LLM chấm độ phù hợp và lưu cache theo brand/ngày. Khi sinh caption, AI lấy trend card được chọn để đưa vào prompt.</p><p>Neo4j bổ sung dữ liệu ở bước viết caption, không làm lại toàn bộ bảng xếp hạng trend. Query chỉ đọc đúng ID trend qua quan hệ <code>CrawledPost - BELONGS_TO -&gt; Trend</code> và <code>CrawledPost - MENTIONS -&gt; Entity</code>, kèm URL bài nguồn. Các node có <code>brand_id</code> của client khác bị loại. Các quan hệ suy diễn như <code>PROMOTED</code> không được đưa vào làm bằng chứng.</p><p>Context graph giúp hiểu ai/cái gì/ở đâu được thảo luận; việc một thương hiệu được nhắc không chứng minh có tài trợ, đại diện hay quan hệ với sản phẩm đang viết. URL được giữ làm xuất xứ trong prompt, không tự mở website lấy thêm dữ liệu. Neo4j hiện không lưu nguyên văn bài trong đường ingestion này; phần trích đoạn nội dung vẫn đến từ trend card Redis.</p><p>Query có timeout 2 giây, toàn bộ bước graph có deadline 3 giây. Nếu Neo4j lỗi/không có bằng chứng thì tiếp tục với context cũ; không bịa dữ liệu thay thế. Context graph được giữ riêng khỏi nguồn đối chiếu số liệu sản phẩm và không thêm lời gọi LLM.</p><h2 id="_4-tu-du-lieu-đen-ket-qua" tabindex="-1">4. Từ dữ liệu đến kết quả <a class="header-anchor" href="#_4-tu-du-lieu-đen-ket-qua" aria-label="Permalink to &quot;4. Từ dữ liệu đến kết quả&quot;">​</a></h2><ol><li>Business gom context, kiểm tra quyền và giữ credit; gửi request nội bộ tới <code>/api/v1/ai/content/captions/generate</code>.</li><li>AI bổ sung RAG, trend card và bằng chứng Neo4j nếu có, ghép chủ đề, dữ kiện, mẫu giọng, mục tiêu, style của nền tảng và Humanizer.</li><li>Trong một lần sinh thành công, LLM trả JSON gồm đúng ba loại: <code>HOOK_DRIVEN</code>, <code>STORYTELLING</code>, <code>DIRECT_CTA</code>. Humanizer yêu cầu model tự rà câu sáo rỗng và giữ dữ kiện ngay trong request đó, chỉ trả kết quả cuối.</li><li>AI kiểm tra JSON/schema, tách hashtag, tính số ký tự và gắn tín hiệu: số liệu không xuất hiện trong nguồn, có dùng keyword trend không, emoji, lộ prompt, chữ ngoại ngữ bất thường, từ nhạy cảm và độ dài. PhoBERT emotion v12 bổ sung phân bố cảm xúc nếu model tải được; thiếu model thì tín hiệu cảm xúc rỗng.</li><li>API kiểm duyệt từng caption qua dịch vụ text moderation, trả <code>PASSED</code>, <code>WARNING</code>, <code>BLOCKED</code> hoặc <code>NOT_CHECKED</code> cùng lý do.</li><li>Business lưu request, ba kết quả, context và credit vào PostgreSQL <code>ai_caption_generations</code>; trả <code>generationId</code>, captions, context đã dùng và số credit về web. Hệ thống credit còn lưu output thực thi để có thể phát lại kết quả đã có.</li><li>Popup hiển thị ba bài. Khi chọn chèn/thay thế, web cập nhật nội dung editor và gửi lựa chọn về backend; <code>chosen_type</code>, <code>chosen_action</code>, <code>final_text</code>, <code>chosen_at</code> được ghi vào lịch sử. Lưu lựa chọn không tự train lại model.</li><li>Sửa một bài hoặc chuyển nền tảng là request mới, có thể tính credit theo cấu hình hiện tại. Hai thao tác này cũng có Humanizer.</li></ol><p>Kiểm tra số liệu hiện là đối chiếu chữ số trong nguồn, không phải xác minh toàn bộ nội dung bằng nguồn độc lập. Nhiều kiểm tra chỉ gắn cảnh báo; không nên hiểu mọi bài trả về đều đã được xác nhận đúng sự thật.</p><h2 id="_5-provider-model-theo-cau-hinh-local" tabindex="-1">5. Provider/model theo cấu hình local <a class="header-anchor" href="#_5-provider-model-theo-cau-hinh-local" aria-label="Permalink to &quot;5. Provider/model theo cấu hình local&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nhánh</th><th>Cách chọn hiện tại</th></tr></thead><tbody><tr><td>Generate with AI</td><td>Frontend không gửi provider; schema AI mặc định <code>groq</code>, model <code>.env</code> là <code>openai/gpt-oss-120b</code></td></tr><tr><td>Ba caption thông thường</td><td>Theo <code>LLM_PROVIDER</code>; <code>.env</code> hiện đặt <code>gemini</code>, model <code>gemini-3.5-flash-lite</code></td></tr><tr><td>Caption có trend-fit / brand profile</td><td>Theo <code>TREND_FIT_LLM_PROVIDER</code>; <code>.env</code> hiện cũng là <code>gemini</code></td></tr></tbody></table><p>Trong <code>llm_service</code>, Groq có thể chuyển sang Deploy khi gặp lỗi tạm thời/kết quả không đạt; đường provider thất bại có thể chuyển sang Claude nếu có key. Vì vậy một thao tác không phải lúc nào cũng tương đương đúng một request HTTP tới nhà cung cấp. Humanizer không thêm một lần gọi riêng. Kiểm duyệt và chấm trend là các lời gọi riêng với lời gọi sinh caption.</p><p>Đây là cấu hình trên đĩa, chưa phải bằng chứng provider/model nào vừa xử lý thành công một request thực tế.</p><h2 id="_6-điem-con-thieu-can-luu-y" tabindex="-1">6. Điểm còn thiếu cần lưu ý <a class="header-anchor" href="#_6-điem-con-thieu-can-luu-y" aria-label="Permalink to &quot;6. Điểm còn thiếu cần lưu ý&quot;">​</a></h2><ol><li>Hai nút tạo content chưa dùng chung mức context: nhánh nhanh thiếu dữ liệu mà nhánh ba caption đã gom.</li><li>Voice profile còn dựng từ workspace với giá trị mặc định; chưa phải hồ sơ giọng thương hiệu hoàn chỉnh do khách hàng duyệt.</li><li>Form văn bản hiện không gửi ảnh sản phẩm. AI Service có hỗ trợ <code>image_urls</code> ở schema ba caption, nhưng UI/Business request đang dùng chưa nối trường này.</li><li>Context sản phẩm chưa có truy vấn catalog sản phẩm riêng. Tên, thành phần, lợi ích, giá và ưu đãi chỉ có nếu người dùng nhập hoặc tài liệu/context đã chứa.</li><li>Business đang có fallback trend ghi cứng như “Thời trang bền vững” khi upstream lỗi. Nhánh gợi ý hashtag riêng cũng có fallback hashtag về thời trang dưới một số lỗi 503. Các giá trị này có thể không liên quan sản phẩm và không phải kết quả trend pipeline thực tế.</li><li>Dataset train trên máy không được đọc trực tiếp mỗi lần bấm tạo content. Luồng đang suy luận qua API nhà cung cấp; PhoBERT chỉ tham gia kiểm tra cảm xúc. Humanizer là chỉ dẫn prompt, không phải model sinh văn bản mới.</li></ol><h2 id="_7-ma-nguon-đoi-chieu" tabindex="-1">7. Mã nguồn đối chiếu <a class="header-anchor" href="#_7-ma-nguon-đoi-chieu" aria-label="Permalink to &quot;7. Mã nguồn đối chiếu&quot;">​</a></h2><ul><li>Web form: <code>brandhub-web/src/pages/editor/components/AIGeneratePanel.tsx</code>.</li><li>Web request nhanh: <code>brandhub-web/src/services/aiGenerationService.ts</code>.</li><li>Popup ba caption: <code>brandhub-web/src/components/ai/AiCaptionDialog.tsx</code>.</li><li>Gom brand/client/bài cũ: <code>brandhub-business-service/src/main/java/com/brandhub/business/service/ai/CaptionContextService.java</code>.</li><li>Sinh và lưu ba caption: <code>brandhub-business-service/src/main/java/com/brandhub/business/service/ai/AiCaptionService.java</code>.</li><li>Credit/dispatch: <code>brandhub-business-service/src/main/java/com/brandhub/business/service/AiCreditGenerationService.java</code>.</li><li>API AI: <code>brandhub-ai-service/app/api/v1/endpoints/content.py</code>.</li><li>Prompt/RAG/tín hiệu: <code>brandhub-ai-service/app/services/caption_service.py</code>.</li><li>Provider: <code>brandhub-ai-service/app/services/llm_service.py</code>.</li><li>Humanizer: <code>brandhub-ai-service/app/utils/humanizer.py</code>.</li><li>Context Neo4j: <code>brandhub-ai-service/app/services/trend_fit/graph_context.py</code>.</li></ul><h2 id="_8-kiem-chung-phan-neo4j" tabindex="-1">8. Kiểm chứng phần Neo4j <a class="header-anchor" href="#_8-kiem-chung-phan-neo4j" aria-label="Permalink to &quot;8. Kiểm chứng phần Neo4j&quot;">​</a></h2><p>Ngày 03/11/2026: <code>EXPLAIN</code> query trên Neo4j thật thành công; đọc một trend có bằng chứng trả 3 bài nguồn, 5 lượt nhắc thực thể, context 692 ký tự. Không ghi database hoặc gọi AI sinh bài có phí. Bộ test caption, graph, API và trend-fit ban đầu đạt 93 test; kết quả kiểm tra giới hạn ký tự bổ sung được lưu tại <code>docs/feature/caption-neo4j-context/test.md</code>.</p>`,32)])])}const u=t(a,[["render",h]]);export{p as __pageData,u as default};
